    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def bfs(start):
        queue = deque([(start, [grid[start[0]][start[1]])])
        visited = set([start])

        while queue:
            current, path = queue.popleft()
            if len(path) == k:
                return path

            for dx, dy in directions:
