from sympy import isprime

def prime_fib(n: int) -> int:
    def fib_generator():
        a, b = 0, 1
        while True:
            a, b = b, a + b
            yield a

    fib_iter = fib_generator()
    prime_fibs = [next(fib_iter) for _ in range(n)]
    while not isprime(prime_fibs[-1]):
        prime_fibs.append(next(fib_iter))
    return prime_fibs[-1]

