def tri(n: int) -> List[int]:
    if n < 1:
        return []
    result = [1, 3, 2]
    for i in range(3, n + 1):
        if i % 2 == 0:
            result.append(result[i - 1] + result[i - 2])
        else:
            result.append(result[i - 1] + result[i - 2] + result[i + 1])
    return result[:n + 1]

