def find_solution(a, b, n):
    # Check if a or b is zero and if n is not divisible by the other
    if a == 0 and n % b != 0:
        return None
    if b == 0 and n % a != 0:
        return None

    # Initialize variables for the extended Euclidean algorithm
    x, y, r, s, t = 0, 1, n, 0, 1

    # Perform the extended Euclidean algorithm
    while r != 0:
        q = r // b
        r, s, t = b, t - q * s, s
        b, x, y = r, y - q * x, x

    # Check if the solution exists
    if b != 1:
        return None

    # Return the solution
    return (y, -x)

