def max_sum_increasing_subseq(arr, n, i, k):
    # Initialize a 2D list to store maximum sum subsequence up to each index
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the dp table
    for j in range(n):
        dp[j][j] = arr[j]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = arr[j]
            for l in range(i, j):
                if arr[l] < arr[j]:
                    dp[i][j] = max(dp[i][j], dp[i][l] + arr[j])

    # Find the maximum sum subsequence including the kth element
    max_sum = 0
    for j in range(k + 1, n):
        max_sum = max(max_sum, dp[i][j])

    return max_sum

