def max_sum_increasing_subseq(nums, n, i, k):
    # Initialize the DP array with zeros
    dp = [0] * (n + 1)
    for j in range(1, n + 1):
        dp[j] = nums[j - 1]

    # Fill the DP array to find the maximum sum increasing subsequence
    for j in range(2, n + 1):
        for k in range(1, j):
            if nums[j - 1] > nums[k - 1]:
                dp[j] = max(dp[j], dp[k] + nums[j - 1])

    # Return the maximum sum including the kth element
    return dp[k]

