    # Stack to keep track of opening brackets
    stack = []

    # Iterate through each character in the expression
    for i in expr:
        # If the character is an opening bracket, push it onto the stack
        if i in match.values():
            stack.append(i)
        # If the character is a closing bracket, check for a matching opening bracket
        elif i in match.keys():
            # If the stack is empty or the top of the stack doesn't match the current closing bracket, return False
            if not stack or stack[-1] != match[i]:
                return False
            # If a match is found, pop the top of the stack
            stack.pop()
    # If the stack is empty, all brackets were matched, so return True
    return len(stack) == 0

