def pancake_sort(arr):
    n = len(arr)
    for i in range(n - 1, 0, -1):
        max_idx = i
        for j in range(i):
            if arr[j] > arr[max_idx]:
                max_idx = j
        arr[max_idx], arr[i] = arr[i], arr[max_idx]
        arr[:i + 1] = reversed(arr[:i + 1])
    return arr

