def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = 1

    for i in range(1, m + 1):
        for j in range(2, n + 1):
            for k in range(2 * i, i * 2 + 1, i):
                if k <= m:
                    dp[i][j] += dp[k][j - 1]

    return dp[m][n]

