def sumofFactors(n):
    result = 1
    i = 2
    while i * i <= n:
        count = 0
        curr_sum = 1
        curr_term = 1
        while n % i == 0:
            count += 1
            n //= i
            if count % 2 == 1:
                curr_sum = curr_sum + i
            else:
                curr_term = curr_term * i
        result *= curr_sum
        i += 1
    if n >= 2:
        result *= (1 + n)
    return result

