def bell_Number(n):
    bell = [[0 for i in range(n+1)] for j in range(n+1)]
    bell[0][0] = 1

    for i in range(1, n+1):
        for j in range(i+1):
            if j == 0:
                bell[i][j] = bell[i-1][j]
            else:
                bell[i][j] = bell[i-1][j-1] + bell[i][j-1]

    return bell[n][n]

assert bell_Number(2) == 2

