def is_magic_square(matrix):
    n = len(matrix)
    if n != 4:
        return False

    # Check row sums
    for row in matrix:
        if sum(row) != n * (n + 1) // 2:
            return False

    # Check column sums
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != n * (n + 1) // 2:
            return False

    # Check diagonal sums
    if sum(matrix[i][i] for i in range(n)) != n * (n + 1) // 2 or sum(matrix[i][n-i-1] for i in range(n)) != n * (n + 1) // 2:
        return False

    return True

def is_magic_square(matrix):
    """
    Check if a given matrix is a magic square.
    A magic square is a square grid filled with distinct numbers from 1 to n^2, where the sum of
    the numbers in each row, each column, and both main diagonals are all the same.
    """
    n = len(matrix)
    magic_sum = n * (n**2 + 1) // 2  # Magic sum for a magic square of size n x n

    # Check the sum of each row
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check the sum of each column
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != magic_sum:
            return False

    # Check the sum of the main diagonals
    if sum(matrix[i][i] for i in range(n)) != magic_sum or sum(matrix[i][n-i-1] for i in range(n)) != magic_sum:
        return False

    return True

from typing import List

def is_magic_square(matrix: List[List[int]]) -> bool:
    n = len(matrix)
    if n == 0:
        return False

    # Check if the matrix is 4x4
    if n != 4:
        return False

    # Calculate the sum of the first row
    sum_first_row = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != sum_first_row:
            return False

    # Check if all columns have the same sum
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != sum_first_row:
            return False

    # Check if the diagonals have the same sum
    diagonal_sum = sum(matrix[i][i] for i in range(n))
    if diagonal_sum != sum_first_row:
        return False

    # Check if the anti-diagonals have the same sum
    anti_diagonal_sum = sum(matrix[i][n-i-1] for i in range(n))
    if anti_diagonal_sum != sum_first_row:
        return False

    return True

