def is_samepatterns(words, patterns):
    def transform(s):
        seen = {}
        result = []
        index = 0
        for char in s:
            if char not in seen:
                seen[char] = index
                index += 1
            result.append(str(seen[char]))
        return " ".join(result)

    return [transform(word) for word in words] == [transform(pattern) for pattern in patterns]

