def maxAverageOfPath(costs):
    # Initialize the first cell with the cost
    costs[0][0] = costs[0][0]

    # Fill the first row
    for i in range(1, len(costs)):
        costs[i][0] += costs[i - 1][0]

    # Fill the first column
    for j in range(1, len(costs[0])):
        costs[0][j] += costs[0][j - 1]

    # Fill the rest of the matrix
    for i in range(1, len(costs)):
        for j in range(1, len(costs[0])):
            # Update the current cell with the maximum of top or left cell plus the current cell's cost
            costs[i][j] += max(costs[i - 1][j], costs[i][j - 1])

    # Return the average of the maximum path
    return costs[-1][-1] / len(costs) / len(costs[0])

