assert maxAverageOfPath([[1, 2, 3], [6, 5, 4], [7, 3, 9]]) == 5.2

def count_reverse_pairs(str_list):
    # Initialize a dictionary to count occurrences of each string
    d = {}
    for i in str_list:
        # If the string is not in the dictionary, initialize its count to 1
        if i not in d:
            d[i] = 1
        else:
            # If the string is already in the dictionary, increment its count
            d[i] += 1
    # Calculate the total number of reverse pairs
    n = 0
    for i in d.keys():
        # If the count of the string is greater than 1, calculate the number of reverse pairs
        if d[i] > 1:
            n += d[i] * (d[i] - 1) // 2
    return n

